"use server";

import { Resend } from "resend";
import { z } from "zod";

export type WaitlistState = { ok: boolean; message: string } | null;

const emailSchema = z.email("Enter a valid email");

/** Adds the email to the Resend audience. Created per call so builds work without keys. */
export async function joinWaitlist(_prev: WaitlistState, form: FormData): Promise<WaitlistState> {
  const parsed = emailSchema.safeParse(form.get("email"));
  if (!parsed.success) return { ok: false, message: parsed.error.issues[0]!.message };
  const audienceId = process.env.RESEND_AUDIENCE_ID;
  if (!process.env.RESEND_API_KEY || !audienceId) return { ok: false, message: "The waitlist isn't set up yet." };

  const { error } = await new Resend(process.env.RESEND_API_KEY).contacts.create({ email: parsed.data, audienceId });
  if (error) return { ok: false, message: "Couldn't save it. Please try again." };
  return { ok: true, message: "You're in! We'll let you know when we launch." };
}

"use client";

import { useActionState } from "react";

import { joinWaitlist, type WaitlistState } from "@/app/actions/waitlist";

export function WaitlistForm() {
  const [state, action, pending] = useActionState<WaitlistState, FormData>(joinWaitlist, null);
  return (
    <form action={action} className="mx-auto flex w-full max-w-md flex-col gap-3 sm:flex-row">
      <label htmlFor="email" className="sr-only">Email</label>
      <input id="email" name="email" type="email" required autoComplete="email" placeholder="tu@email.com" className="h-11 flex-1 rounded-full border px-4" />
      <button type="submit" disabled={pending} className="h-11 rounded-full bg-neutral-950 px-6 text-white disabled:opacity-60">
        {pending ? "Joining…" : "Join"}
      </button>
      <p aria-live="polite" className={`text-sm sm:basis-full ${state?.ok ? "text-green-700" : "text-red-700"}`}>{state?.message}</p>
    </form>
  );
}

import { WaitlistForm } from "@/components/waitlist-form";

